package li.cil.oc.config;

import com.google.common.net.InetAddresses;
import com.typesafe.config.*;
import java.util.*;
import java.util.regex.Pattern;
import org.apache.maven.artifact.versioning.DefaultArtifactVersion;

/** Upstream version patches and explicit modern identifier migration in the same HOCON document. */
public final class SettingsMigration {
    public static final int SCHEMA_VERSION=1;
    private static final String PREFIX="opencomputers.";
    private static final Pattern VERSION=Pattern.compile("^(\\d+)(?:\\.(\\d+))?(?:\\.(\\d+))?(.*)$");
    public record Result(Config config,List<String> changes){public boolean changed(){return !changes.isEmpty();}}
    private SettingsMigration(){}
    private static boolean older(String version,String target){if(!VERSION.matcher(version).matches())throw new IllegalArgumentException("Invalid opencomputers.version '"+version+"': expected a dotted numeric version");return new DefaultArtifactVersion(version).compareTo(new DefaultArtifactVersion(target))<0;}
    private static Config reset(Config config,Config defaults,List<String> changes,String... paths){for(String path:paths){String key=PREFIX+path;if(defaults.hasPath(key)){if(!config.hasPath(key)||!config.getValue(key).equals(defaults.getValue(key))){config=config.withValue(key,defaults.getValue(key));changes.add("reset "+key+" to the upstream migration default");}}else if(config.hasPath(key)){config=config.withoutPath(key);changes.add("remove obsolete "+key);}}return config;}
    private static List<String> strings(Config config,String path){return config.hasPath(path)?config.getStringList(path):List.of();}
    private static String addressRule(String action,String address){String literal=address.split("/",2)[0];return action+(InetAddresses.isInetAddress(literal)?" ip:":" domain:")+address;}
    private static Config filterLists(Config config,Config defaults,List<String> changes){List<String> white=strings(config,PREFIX+"internet.whitelist"),black=strings(config,PREFIX+"internet.blacklist");if(white.isEmpty()&&black.isEmpty())return config;List<String> rules=new ArrayList<>();for(String address:black)rules.add(addressRule("deny",address));for(String address:white)rules.add(addressRule("allow",address));if(!white.isEmpty())rules.add("deny all");rules.addAll(config.hasPath(PREFIX+"internet.filteringRules")?config.getStringList(PREFIX+"internet.filteringRules"):defaults.getStringList(PREFIX+"internet.filteringRules"));for(String key:List.of("internet.whitelist","internet.blacklist"))if(config.hasPath(PREFIX+key)){ConfigValue original=config.getValue(PREFIX+key);List<String> comments=new ArrayList<>(List.of("No longer used! See internet.filteringRules.","Previous contents:"));for(String value:config.getStringList(PREFIX+key))comments.add('"'+value+'"');ConfigValue replacement=ConfigValueFactory.fromIterable(List.of()).withOrigin(original.origin().withComments(comments));config=config.withValue(PREFIX+key,replacement);}config=config.withValue(PREFIX+"internet.filteringRules",ConfigValueFactory.fromIterable(rules).withOrigin(defaults.getValue(PREFIX+"internet.filteringRules").origin()));changes.add("migrate internet.whitelist/blacklist to ordered filteringRules");return config;}
    public static Result patch(Config raw,Config defaults,String currentVersion){Config config=raw;List<String> changes=new ArrayList<>();boolean marker=config.hasPath(PREFIX+"configSchemaVersion");double schemaValue=marker?SettingsValidation.number(config.getConfig("opencomputers"),"configSchemaVersion"):0;if(schemaValue!=Math.floor(schemaValue)||schemaValue<0||schemaValue>SCHEMA_VERSION)throw SettingsValidation.bad(config.getConfig("opencomputers"),"configSchemaVersion","an integer in 0.."+SCHEMA_VERSION);int schema=(int)schemaValue;String version=config.hasPath(PREFIX+"version")?config.getString(PREFIX+"version"):"0.0.0";
        boolean existingPort=version.equals(currentVersion)||version.matches("0\\.1\\.\\d+(?:[-+].*)?");
        if(schema==0&&!existingPort){if(older(version,"1.5.20"))config=reset(config,defaults,changes,"switch.relayDelayUpgrade");if(older(version,"1.6.2"))config=reset(config,defaults,changes,"nanomachines.potionWhitelist");if(older(version,"1.7.2"))config=reset(config,defaults,changes,"power.cost.wirelessCostPerRange","misc.maxWirelessRange","misc.maxOpenPorts","computer.cpuComponentCount");if(older(version,"1.8.0"))config=reset(config,defaults,changes,"computer.robot.limitFlightHeight","robot.limitFlightHeight");if(older(version,"1.8.10"))config=reset(config,defaults,changes,"misc.maxClipboard");if(older(version,"1.8.3"))config=filterLists(config,defaults,changes);}
        if(schema==0&&existingPort)config=filterLists(config,defaults,changes);
        for(String path:List.of("internet.whitelist","internet.blacklist"))if(config.hasPath(PREFIX+path)&&!config.getStringList(PREFIX+path).isEmpty())throw new ConfigException.BadValue(config.getValue(PREFIX+path).origin(),PREFIX+path,"removed option is not empty; migrate its entries into internet.filteringRules before starting");
        String blacklist=PREFIX+"integration.peripheralBlacklist";if(config.hasPath(blacklist)){var old=config.getStringList(blacklist);LinkedHashSet<String> modern=new LinkedHashSet<>();for(String entry:old)modern.add(entry.equals("net.minecraft.tileentity.TileEntityCommandBlock")?"net.minecraft.world.level.block.entity.CommandBlockEntity":entry);if(!new ArrayList<>(modern).equals(old)){config=config.withValue(blacklist,ConfigValueFactory.fromIterable(modern).withOrigin(config.getValue(blacklist).origin()));changes.add("migrate vanilla command-block peripheral class and remove duplicate entries");}}
        String potions=PREFIX+"nanomachines.potionWhitelist";if(config.hasPath(potions)){List<?> old=config.getAnyRefList(potions);List<String> modern=SettingsValidation.potionWhitelist(config.getConfig("opencomputers"));if(!old.equals(modern)){config=config.withValue(potions,ConfigValueFactory.fromIterable(modern).withOrigin(config.getValue(potions).origin()));changes.add("migrate vanilla numeric potion ids to stable effect resource names");}}
        for(String name:List.of("chunkloader.dimBlacklist","chunkloader.dimWhitelist")){String path=PREFIX+name;if(config.hasPath(path)){List<?> old=config.getAnyRefList(path);List<Object> modern=SettingsValidation.dimensions(config.getConfig("opencomputers"),name);if(!old.equals(modern)){config=config.withValue(path,ConfigValueFactory.fromIterable(modern).withOrigin(config.getValue(path).origin()));changes.add("canonicalize "+path+" dimension resource names");}}}
        // A renamed FE key must inherit an explicit legacy RF value instead of replacing user tuning.
        if(!config.hasPath(PREFIX+"power.value.ForgeEnergy")&&config.hasPath(PREFIX+"power.value.RedstoneFlux")){config=config.withValue(PREFIX+"power.value.ForgeEnergy",config.getValue(PREFIX+"power.value.RedstoneFlux"));changes.add("inherit power.value.ForgeEnergy from the existing RedstoneFlux value");}
        if(schema<SCHEMA_VERSION){config=config.withValue(PREFIX+"configSchemaVersion",(defaults.hasPath(PREFIX+"configSchemaVersion")?defaults.getValue(PREFIX+"configSchemaVersion"):ConfigValueFactory.fromAnyRef(SCHEMA_VERSION)));changes.add("mark the NeoForge configuration schema");}
        if(!version.equals(currentVersion)){config=config.withValue(PREFIX+"version",defaults.getValue(PREFIX+"version"));changes.add("update generated version from "+version+" to "+currentVersion);}
        return new Result(config,List.copyOf(changes));}
}
